contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint amount) public {
        require(amount > 0);
        uint contractBalanceBefore = address(c).balance;
        bool reverted;
        c.withdrawAll(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }
        uint contractBalanceAfter = address(c).balance;
        assert(reverted || contractBalanceAfter == contractBalanceBefore);
    }

    receive() external payable {}
}

